import fs from 'fs'

import { resolveModulePath } from './resolve.js'

export interface ModuleExports {
  /**
   * Node (typically the name identifier) for each export, keyed by export name
   * (including `'default'`). Used to compute go-to-definition target spans.
   */
  exportNodes: Map<string, ts.Node>
  hasDefault: boolean
  /** All named (non-default) exports of the module. */
  named: string[]
  /** The parsed source file of the resolved module. */
  sourceFile: ts.SourceFile
}

function hasModifier(
  ts: typeof import('typescript'),
  node: ts.Node,
  kind: ts.SyntaxKind,
): boolean {
  const modifiers = (ts.canHaveModifiers(node) ? ts.getModifiers(node) : undefined) ?? []
  return modifiers.some((m) => m.kind === kind)
}

/**
 * Reads and parses the module at `filePath`, returning its exports. The file is
 * read fresh from disk (falling back to the language service host snapshot when
 * available) so that unsaved editor state is respected where possible.
 */
export function getModuleExports(
  ts: typeof import('typescript'),
  filePath: string,
  readFile: (path: string) => string | undefined,
  compilerOptions: ts.CompilerOptions,
  depth = 0,
): ModuleExports | null {
  const text = readFile(filePath)
  if (text === undefined) {
    return null
  }

  const sourceFile = ts.createSourceFile(
    filePath,
    text,
    ts.ScriptTarget.Latest,
    /* setParentNodes */ true,
    /^.*\.(tsx|jsx)$/.test(filePath) ? ts.ScriptKind.TSX : undefined,
  )

  const named = new Set<string>()
  const exportNodes = new Map<string, ts.Node>()
  let hasDefault = false

  const addNamed = (name: string, node: ts.Node) => {
    if (name === 'default') {
      hasDefault = true
    } else {
      named.add(name)
    }
    if (!exportNodes.has(name)) {
      exportNodes.set(name, node)
    }
  }

  for (const statement of sourceFile.statements) {
    // export default <expr>  /  export = <expr>
    if (ts.isExportAssignment(statement)) {
      if (!statement.isExportEquals) {
        addNamed('default', statement.expression ?? statement)
      }
      continue
    }

    // export { a, b as c }  /  export { a } from './m'  /  export * from './m'
    if (ts.isExportDeclaration(statement)) {
      const { exportClause, moduleSpecifier } = statement

      if (exportClause && ts.isNamedExports(exportClause)) {
        for (const element of exportClause.elements) {
          addNamed(element.name.text, element.name)
        }
        continue
      }

      if (exportClause && ts.isNamespaceExport(exportClause)) {
        // export * as ns from './m'
        addNamed(exportClause.name.text, exportClause.name)
        continue
      }

      // export * from './m'  -> merge re-exported names (bounded recursion)
      if (!exportClause && moduleSpecifier && ts.isStringLiteral(moduleSpecifier) && depth < 4) {
        const resolved = resolveModulePath(ts, {
          compilerOptions,
          currentDirectory: '',
          referencingDir: dirName(filePath),
          spec: moduleSpecifier.text,
        })
        if (resolved) {
          const reExported = getModuleExports(ts, resolved, readFile, compilerOptions, depth + 1)
          if (reExported) {
            for (const name of reExported.named) {
              addNamed(name, statement)
            }
          }
        }
      }
      continue
    }

    if (!hasModifier(ts, statement, ts.SyntaxKind.ExportKeyword)) {
      continue
    }

    const isDefault = hasModifier(ts, statement, ts.SyntaxKind.DefaultKeyword)

    if (ts.isFunctionDeclaration(statement) || ts.isClassDeclaration(statement)) {
      if (isDefault) {
        addNamed('default', statement.name ?? statement)
      }
      if (statement.name) {
        addNamed(statement.name.text, statement.name)
      }
      continue
    }

    if (ts.isVariableStatement(statement)) {
      for (const decl of statement.declarationList.declarations) {
        if (ts.isIdentifier(decl.name)) {
          addNamed(decl.name.text, decl.name)
        }
      }
      continue
    }

    if (
      ts.isInterfaceDeclaration(statement) ||
      ts.isTypeAliasDeclaration(statement) ||
      ts.isEnumDeclaration(statement) ||
      ts.isModuleDeclaration(statement)
    ) {
      const name = (statement as { name?: ts.Node }).name
      if (name && ts.isIdentifier(name as ts.Node)) {
        addNamed((name as ts.Identifier).text, name as ts.Node)
      }
    }
  }

  return {
    exportNodes,
    hasDefault,
    named: Array.from(named),
    sourceFile,
  }
}

function dirName(filePath: string): string {
  const normalized = filePath.replace(/\\/g, '/')
  const idx = normalized.lastIndexOf('/')
  return idx === -1 ? '.' : normalized.slice(0, idx)
}

/**
 * Default file reader used by the plugin. Prefers the provided host reader
 * (which reflects unsaved editor buffers) and falls back to the filesystem.
 */
export function createFileReader(
  hostReadFile?: (path: string) => string | undefined,
): (path: string) => string | undefined {
  return (path: string) => {
    if (hostReadFile) {
      const fromHost = hostReadFile(path)
      if (fromHost !== undefined) {
        return fromHost
      }
    }
    try {
      return fs.readFileSync(path, 'utf-8')
    } catch {
      return undefined
    }
