import fs from 'fs'
import path from 'path'

const RESOLVE_EXTENSIONS = [
  '.ts',
  '.tsx',
  '.d.ts',
  '.js',
  '.jsx',
  '.mjs',
  '.cjs',
  '.mts',
  '.cts',
]

const INDEX_BASENAMES = ['index']

function fileExists(p: string): boolean {
  try {
    return fs.statSync(p).isFile()
  } catch {
    return false
  }
}

function directoryExists(p: string): boolean {
  try {
    return fs.statSync(p).isDirectory()
  } catch {
    return false
  }
}

/**
 * Given a candidate path (which may or may not include an extension, and may be
 * a directory), attempts to resolve it to an existing module file on disk.
 */
export function resolveFile(candidate: string): null | string {
  const normalized = candidate.replace(/\\/g, '/')

  if (fileExists(normalized)) {
    return normalized
  }

  for (const ext of RESOLVE_EXTENSIONS) {
    if (fileExists(normalized + ext)) {
      return normalized + ext
    }
  }

  if (directoryExists(normalized)) {
    for (const base of INDEX_BASENAMES) {
      for (const ext of RESOLVE_EXTENSIONS) {
        const indexPath = path.posix.join(normalized, base + ext)
        if (fileExists(indexPath)) {
          return indexPath
        }
      }
    }
  }

  return null
}

/**
 * Resolves the effective `baseUrl` used for tsconfig `paths` alias resolution.
 */
function resolveBaseUrl(compilerOptions: ts.CompilerOptions, currentDirectory: string): string {
  const baseUrl = compilerOptions.baseUrl
  if (baseUrl) {
